-- 2217 🏋️ Exercises from the book "possession-with-purpose-to-maximise-performance-50-practices-youth-to-pro-traini" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'possession-with-purpose-to-maximise-performance-50-practices-youth-to-pro-traini');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Four-box rotating 6v2 one-touch keep-ball', 'rondo', 'overload', 'in_possession', 39, 39, 'Resistance Day Directional Possession Practice 1', 'Adam Owen', 'Keep the ball under control while circulating it quickly from one box to the next.', 'Four 12m boxes laid out side by side; 6 blues and 2 reds start in one box, other reds wait by the next boxes.', 'Blues keep the ball 6v2 on one touch; after 6 passes one blue moves into the next box to receive and the group follows to keep going. On the coach''s whistle 2 fresh reds sprint in to press in the new box.', 'All players one touch; defenders may only enter the next box after its first touch; blues rotate through all four boxes, reds aim to win the ball 5 times. 3 min reps x 4 sets (12 min work).', NULL, 'Support angles, timing of the move to the next box, quick transitions, speed of press, fast reactions.', '6v2 (12 players)', 12, 12, 'Four 12m boxes', 12.0, 12.0, 14.0, false, false, true, NULL, 10),
  ('4v4+4 triangle with central joker', 'possession', 'overload', 'in_possession', 40, 40, 'Resistance Day Directional Possession Practice 2', 'Adam Owen', 'Use a central overload through a link player to find the outside players.', 'Triangle with 20m sides; a yellow outside support player in each corner and one central joker inside; two teams of 4 play inside.', 'The team on the ball must combine through the joker before playing out to a corner player, then keep circulating and switching play under pressure.', 'Play through the joker before an outside player. 1.5 min reps x 6 sets (9 min work).', 'The joker can swap places with any outside player to add rotations.', 'Quick passing, movement and support angles to open the middle; decision-making under pressure.', '4v4 +3 outside +1 joker (12 players)', 12, 12, 'Triangle 20 x 20 x 20 m', 20.0, 20.0, 15.0, false, false, true, NULL, 20),
  ('4v4+4 one-touch one-twos with outside boxes', 'positional_game', 'overload', 'in_possession', 41, 41, 'Resistance Day Directional Possession Practice 3', 'Adam Owen', 'Combine quickly to open and use chances to switch play.', '20x20m central diamond-shaped area with a small box on each of its four sides holding a yellow outside player; two teams of 4 inside.', 'The team in possession must make a central pass before it may play to an outside player; a one-two with an outside player scores a point.', 'Everyone one touch; outside only after a central pass; 1 point per completed one-two with an outside player. 2 min reps x 6 sets (12 min work).', NULL, 'Quick support, sharp movement, awareness in central areas, timing of support, switching play.', '4v4+4 (12 players)', 12, 12, '20 x 20 m', 20.0, 20.0, 18.0, false, false, true, NULL, 30),
  ('3v3+2 end targets switching game', 'positional_game', 'overload', 'in_possession', 42, 42, 'Resistance Day Directional Possession Practice 4', 'Adam Owen', 'Spot and execute timely switches of play through target players.', '15x10m area with one target player at each end; 3v3 inside.', 'Teams move the ball fast and look to go from one end target to the other, using quick one-twos with the targets to change the direction of play.', 'Target players one touch. 2 min reps x 6 sets (12 min work).', NULL, 'High tempo, sharp decisions, accurate passing, constant movement, speed of support.', '3v3+2 (groups of 8)', 8, 8, '15 x 10 m', 15.0, 10.0, 15.0, false, false, true, NULL, 40),
  ('3v3+6 end-player overload switching game', 'positional_game', 'overload', 'in_possession', 43, 43, 'Resistance Day Directional Possession Practice 5', 'Adam Owen', 'Use overloads to draw pressure and create chances to switch play.', '25x20m area with 3 support players on each end line; 3v3 in the middle.', 'The team on the ball uses the end players to build overloads and move the ball from one end to the other, playing through or around the 3 defenders with quick circulation and triangles.', 'The player who passes into an end player cannot get it straight back; support must come from elsewhere. 2 min reps x 6 sets (12 min work).', NULL, 'Constant movement to make triangles and good support angles; third-player movement; decisions under pressure.', '3v3+6 (12 players)', 12, 12, '25 x 20 m', 25.0, 20.0, 15.0, false, false, true, NULL, 50),
  ('4v4 end targets rotate in on receiving', 'positional_game', 'opposed', 'in_possession', 44, 44, 'Resistance Day Directional Possession Practice 6', 'Adam Owen', 'Keep the ball at high tempo using rotations and good support angles.', '15x12m area; 4v4 inside, each team also has one target player at each end (4 targets in all).', 'Teams keep the ball under pressure and look to switch side to side; when the ball goes to a target, the target dribbles into the area and the passer immediately rotates out to take their spot.', 'Passer to a target must swap places with that target. 3 min reps x 4 sets (12 min work).', NULL, 'Scan, move the ball quickly, movement off the ball, rotate to support, decide under pressure.', '4v4 +4 targets (12 players)', 12, 12, '15 x 12 m', 15.0, 12.0, 14.0, false, false, true, NULL, 60),
  ('4v4v4 three-zone keep-ball and transfer', 'positional_game', 'overload', 'in_possession', 45, 45, 'Resistance Day Directional Possession Practice 7', 'Adam Owen', 'Keep control by moving the ball efficiently from zone to zone.', '29x12m area: two 12m end zones and a 5m middle zone with 3 mannequins; three teams of 4, one in each end zone and the defending team split 2 in the active end zone and 2 in the middle zone.', 'The team in the active end zone plays 4v2 against two pressers and, after 5 passes, plays the ball across into the far end zone to the waiting team; the two middle-zone defenders try to cut out the transfer pass.', '5 passes before playing across; the 2 middle defenders may intercept in the middle zone. 3 min reps x 4 sets (12 min work).', NULL, 'Quick movement, strong support angles, read passing lanes, correct body shape, accurate passes between zones.', '4v4v4 (12 players)', 12, 12, '29 x 12 m', 29.0, 12.0, 20.0, false, false, true, NULL, 70),
  ('6v3 keep-ball with 4 mini goals counter-press', 'transition', 'overload', 'to_defend', 46, 46, 'Resistance Day Directional Possession Practice 8', 'Adam Owen', 'Keep the ball and counter-press straight away when it is lost.', '15x12m grid with a mini goal on each of the four sides; 6 blues v 3 reds inside.', 'Blues keep the ball 6v3 with quick passing and support. If the reds win it they attack any mini goal by dribbling or passing; the blues react instantly to press the ball and stop them scoring.', 'Reds score in any of the 4 mini goals after a regain. 2 min reps x 6 sets (12 min work).', NULL, 'Support angles, awareness of the 3 pressers, fast reactions, immediate pressure on the ball after losing it.', '6v3 (groups of 9)', 9, 9, '15 x 12 m', 15.0, 12.0, 15.0, true, false, true, NULL, 80),
  ('4v4+1 joker keep-ball and counter-press', 'transition', 'overload', 'to_defend', 48, 48, 'Resistance Day Transitional Possession Practice 1', 'Adam Owen', 'Keep the ball using an extra player and counter-press quickly after losing it.', '20x20m area; two teams of 4 plus one joker who plays for the team on the ball.', 'The team in possession uses the joker to build a numbers-up around the ball and circulate it; when possession is lost, the team presses at once to block forward options and win it back.', 'Joker always with the team in possession. 3 min reps x 3 sets (9 min work).', NULL, 'Support on several sides of the ball, width and depth, use the spare player, quick ball speed, close passing lanes, immediate counter-press.', '4v4+1 (groups of 9)', 9, 9, '20 x 20 m', 20.0, 20.0, 18.0, false, false, false, NULL, 90),
  ('Octagon 3v3+8 switch places with outsider', 'possession', 'overload', 'in_possession', 49, 49, 'Resistance Day Transitional Possession Practice 2', 'Adam Owen', 'Keep the ball with rotations and quick support from outside players.', 'Octagon about 20x20m; 3v3 inside with 8 outside support players around the edge (4 per team).', 'The team on the ball uses its 4 outside players to keep possession 7v3. When an inside player passes to an outside player, the two quickly swap positions.', 'Inside-to-outside pass means passer and receiver swap places. 1.5 min reps x 8 sets (12 min work).', NULL, 'Constant rotation, alertness, quick support, keep shape and structure, decisions under pressure.', '3v3+8 (14 players)', 14, 14, '20 x 20 m octagon', 20.0, 20.0, 20.0, false, false, false, NULL, 100),
  ('6v2 two-box rondo, play into next box', 'rondo', 'overload', 'in_possession', 50, 50, 'Resistance Day Transitional Possession Practice 3', 'Adam Owen', 'Keep the ball and progress into the next box with fast support.', 'Two 10m boxes side by side (20x10m total); 6 blues v 2 reds in one box.', 'Blues complete 5 passes then play into the other box; everyone moves across quickly and the 6v2 carries on there with the same aim.', '5 passes before playing into the other box. 2 min reps x 5 sets (10 min work).', NULL, 'Supporting angles, open body to receive, quick reaction between boxes, team compactness, timing of support.', '6v2 (groups of 8)', 8, 8, '20 x 10 m (2 x 10m boxes)', 20.0, 10.0, 15.0, false, false, true, NULL, 110),
  ('4v2 rondo expanding to 6v4 mini goals', 'transition', 'overload', 'to_defend', 51, 51, 'Resistance Day Transitional Possession Practice 4', 'Adam Owen', 'Keep the ball and react quickly when the game expands into a bigger transition game.', 'Small central box inside a 15x15m area with a mini goal at each corner; 4 blues v 2 reds in the box, 4 yellows waiting outside.', 'Blues keep a 4v2 rondo. When the reds win or touch the ball it becomes 6v4 in the full area with the yellows joining the reds; the 4 blues counter-press to win it back and then score in any of the 4 mini goals, which the others defend.', 'Red touch/win triggers the 6v4; blues score in any mini goal after regaining. 2.5 min reps x 4 sets (10 min work).', NULL, 'Counter-pressing, quick reactions, support play, decisions under pressure.', '4v2 then 6v4 (groups of 10)', 10, 10, '15 x 15 m', 15.0, 15.0, 14.0, true, false, true, NULL, 120),
  ('6v3 keep-ball then protect 4 mini goals', 'transition', 'overload', 'to_defend', 52, 52, 'Resistance Day Transitional Possession Practice 5', 'Adam Owen', 'Keep the ball and react at once to guard the goals after losing it.', '18x18m area with a mini goal on each side; 6 blues v 3 reds.', 'Blues keep the ball and, after a set number of passes, can score in any mini goal. If the reds win it they must score within a set number of passes; the blues first drop to protect the goals, then press to regain.', 'Blues score after a set pass count; reds must score within a set pass count after a regain. 2 min reps x 6 sets (12 min work).', NULL, 'Support play, decisions under pressure, counter-pressing, quick reactions.', '6v3 (groups of 9)', 9, 9, '18 x 18 m', 18.0, 18.0, 18.0, true, false, true, NULL, 130),
  ('Three-team 8v4 rotating keep-ball', 'transition', 'overload', 'to_defend', 53, 53, 'Resistance Day Transitional Possession Practice 6', 'Adam Owen', 'Keep the ball using width and depth and press fast after losing it.', '25x25m area; three teams of 4, two together in possession against one defending team (8v4).', 'The defenders press, block lanes and force errors. When they win it, the team that lost the ball immediately becomes the defenders and the winning team joins the other team to keep the ball 8v4; it rotates on every turnover.', 'Team that loses the ball becomes the defending team. 3 min reps x 4 sets (12 min work).', NULL, 'Width and depth, ball circulation, pressing intensity, closing space, fast reactions, transition awareness.', '8v4 (3 teams of 4, 12 players)', 12, 12, '25 x 25 m', 25.0, 25.0, 16.0, false, false, false, NULL, 140),
  ('8v4 two-half switch on regain', 'transition', 'overload', 'to_attack', 54, 54, 'Resistance Day Transitional Possession Practice 7', 'Adam Owen', 'Keep the ball and react quickly to switch play into the other half.', '30x30m area split into two halves; 8 blues v 4 reds in one half, the other 4 reds waiting in the opposite half.', 'Blues keep the ball 8v4. When the reds win it they play into the opposite half; the 4 pressing reds move across to join their team in possession and 4 blues move over to press, making it 8v4 again. Runs continuously.', 'On a regain the ball must be played into the opposite half. 4 min reps x 3 sets (12 min work).', 'Add more defenders to make it harder.', 'Keep the ball under pressure, use space, switch play, counter-attacking support, pressing and closing space, transition speed.', '8v4 (16 players, two teams of 8)', 16, 16, '30 x 30 m', 30.0, 30.0, 15.0, false, false, true, NULL, 150),
  ('7v4 octagon keep-ball, link CF and finish', 'transition', 'overload', 'in_possession', 55, 55, 'Resistance Day Transitional Possession Practice 8', 'Adam Owen', 'Keep possession, link through the centre forward and finish the attack.', 'Half pitch with an octagon area in midfield; 7 blues v 4 reds inside, a centre forward ahead near the box with mannequins as a back line, a GK in the full goal and two mini goals behind the octagon for the reds.', 'Blues complete a set number of passes, then play into the centre forward, who links with supporting runners to finish on the big goal. If the reds win it they counter quickly to score in either mini goal.', 'Set number of passes before playing into the CF; reds score in either mini goal on a regain. 2 min reps x 6 sets (12 min work).', NULL, 'Quick possession, support around the ball, forward runs beyond the striker, link play, fast reaction to turnovers, finishing.', '7v4 + CF + GK (16 + GK)', 17, 17, 'Half pitch', NULL, NULL, 18.0, true, true, true, NULL, 160),
  ('6v6+4 two-zone target player combinations', 'positional_game', 'overload', 'in_possession', 63, 63, 'Speed Endurance Day - Directional: Practice 1', 'Adam Owen', 'Keep the ball and play forward into a target player using combinations.', '60x40m split into two end zones with a free middle strip; 3v3 plus a joker in each zone, a target player outside each end.', 'Team keeps the ball in one zone, then moves it to the far zone (a player may drop into the free strip to link). In the far zone they find the end target and get a return pass, then play back across.', NULL, NULL, 'Space, support angles and distances, positive first touch, forward passing, moving between zones.', '6v6 +2 jokers +2 targets (14 + GKs)', 14, 14, '60 x 40 m', 60.0, 40.0, 20.0, false, false, true, NULL, 170),
  ('8v8+4 outside players support rotations', 'positional_game', 'overload', 'in_possession', 64, 64, 'Speed Endurance Day - Directional: Practice 2', 'Adam Owen', 'Keep the ball, switch play and rotate to open passing lines.', '50x45m central area, 8v8 inside; each team has 4 outside players in 5m channels round the edge.', 'Team in possession uses its outside players to move the ball side to side or end to end. When an outside player receives he dribbles in and swaps with the passer.', 'One side/end to the other = 1 goal; 10 straight passes = 1 goal.', NULL, 'Support angles, retention, switching, rotations and place changes, decisions under pressure.', '8v8 +4 outside per team (20)', 20, 20, '50 x 45 m', 50.0, 45.0, 21.0, false, false, true, NULL, 180),
  ('8(+4)v8(+4) switch of play with rotations', 'positional_game', 'overload', 'in_possession', 65, 65, 'Speed Endurance Day - Directional: Practice 3', 'Adam Owen', 'Keep the ball, switch play and rotate to create new passing options.', '40x45m area split into two halves; 8v8 inside and each team has 4 outside players in narrow side channels.', 'Teams keep possession and score by switching side to side, or across the halves through the cones. An outside player who receives steps in and swaps with the passer.', 'Side to side = 1 goal; half to half through cones = 1 goal; 10 straight passes = 1 goal.', NULL, 'Switching, support, rotations, width in possession.', '8v8 +4 outside each (20-24)', 20, 24, '40 x 45 m', 40.0, 45.0, 24.0, false, false, true, NULL, 190),
  ('10v10 play through pole gates', 'positional_game', 'opposed', 'in_possession', 66, 66, 'Speed Endurance Day - Directional: Practice 4', 'Adam Owen', 'Keep the ball and spot the right moment to pass through a gate.', '80x60m with 11 pole gates scattered; teams in their match shape (e.g. 4-3-3).', 'Teams keep possession and play forward, scoring by passing through a gate to a teammate on the far side.', 'Pass and receive through a gate = 1 goal.', 'Require a set number of passes before a gate counts.', 'Team shape, creating space, support angles, forward passing, decisions under pressure.', '10v10', 20, 20, '80 x 60 m', 80.0, 60.0, 18.0, false, false, true, NULL, 200),
  ('10v10 draw then switch into wide boxes', 'positional_game', 'opposed', 'in_possession', 67, 67, 'Speed Endurance Day - Directional: Practice 5', 'Adam Owen', 'Draw the opponent, switch quickly and score in wide areas with third-man runs.', '75x70m with a scoring box in each of the 4 corners.', 'Teams string 8-10 passes to pull the opponents across, then switch quickly and use a third-man run to receive in a corner box.', '8-10 passes = 1 goal; third-man run received in a box = goal; receivers must arrive in the box, not wait in it.', NULL, 'Draw then switch, third-man runs and their timing, attacking wide areas; defenders shift together and stay compact.', '10v10', 20, 20, '75 x 70 m', 75.0, 70.0, 18.0, false, false, true, NULL, 210),
  ('10v10 build-up to goalkeeper targets with pressing', 'positional_game', 'opposed', 'in_possession', 68, 68, 'Speed Endurance Day - Directional: Practice 6', 'Adam Owen', 'Build forward through the lines and press as a team to stop it.', '80x60m with a goalkeeper at each end acting as a target, just inside a penalty box.', 'Attacking team builds up and scores by getting the ball into the keeper''s hands; then that keeper gives it to the opposite keeper to restart. Defending team presses as a unit to protect the middle and win the ball.', 'Ball into GK''s hands inside the box = goal.', NULL, 'Build-up under pressure, positional possession, pressing triggers, compactness.', '10v10 +2 GKs', 22, 22, '80 x 60 m', 80.0, 60.0, 18.0, false, true, true, NULL, 220),
  ('4v4+1 both sides then link to CF and finish', 'combination', 'overload', 'in_possession', 69, 69, 'Speed Endurance Day - Directional: Practice 7', 'Adam Owen', 'Combine through the centre forward and make runs beyond to score.', 'Half pitch with a goal and GK; two wide boxes each holding a 4v4+1 possession game; a centre forward near the box between mannequins.', 'A team hits a set number of passes in its box, then plays into the CF, combines and supporting players run beyond to receive and finish.', 'Set number of passes before attacking.', NULL, 'Angles and distances of support, link play with the CF, timing of runs, finishing.', '4v4+1 x2 + CF + GK (19 + GK)', 20, 20, 'Half pitch', NULL, NULL, 21.0, true, true, true, NULL, 230),
  ('4v4+8 four-team switching transitional possession', 'transition', 'overload', 'to_attack', 71, 71, 'Speed Endurance Day - Transitional: Practice 1', 'Adam Owen', 'Combine quickly, play forward and react at once to transitions.', '40x40m; two teams play 4v4 inside, two other teams of 4 spread round the outside as support players.', 'Team in possession keeps the ball using all support players (12v4) and switches through them; on loss the other team does the same. Teams rotate roles after a set time.', NULL, 'Colour-linked passing; corner combinations; cone touches after passing.', 'Support, combinations, attacking forward, defensive reactions, intensity.', '4v4+8 (16)', 16, 16, '40 x 40 m', 40.0, 40.0, 21.0, false, false, false, NULL, 240),
  ('7v7 counter from overload, two zones', 'transition', 'overload', 'to_attack', 72, 72, 'Speed Endurance Day - Transitional: Practice 2', 'Adam Owen', 'Keep the ball with an overload and react fast on winning it.', '50x25m split into two zones; 7 blues v 6 reds in one zone, 1 red waits in the other zone.', 'Blues keep the ball 7v6. When reds win it they pass quickly to their spare man in the other zone; everyone except one blue moves over and play restarts with roles reversed.', NULL, 'Add a neutral; limit touches; add outside players.', 'Support, retention, quick reaction to winning the ball, moving between areas.', '7v7 (14)', 14, 14, '50 x 25 m', 50.0, 25.0, 21.0, false, false, true, NULL, 250),
  ('3-team 12v6 quick transition reactions', 'transition', 'overload', 'to_defend', 73, 73, 'Speed Endurance Day - Transitional: Practice 3', 'Adam Owen', 'Support play and fast decisions/reactions when the ball changes hands.', '50x50m, three teams of 6.', 'Two teams combine 12v6 to keep the ball against the third. The team that loses the ball becomes the new defenders.', '8 passes = 1 goal.', 'Target players; colour-linked passing; touch limits.', 'Support, passing accuracy, speed of play, quick reaction to losing it.', '6v6+6 (18)', 18, 18, '50 x 50 m', 50.0, 50.0, 21.0, false, false, false, NULL, 260),
  ('8v8 double box: open up vs compact press', 'transition', 'opposed', 'to_defend', 74, 74, 'Speed Endurance Day - Transitional: Practice 4', 'Adam Owen', 'Keep the ball using the whole area and make quick defensive transitions.', '40x40m: a 35m central square with a 5m outer channel round it (two boxes).', 'Possession team uses both boxes to stretch the play; defenders must stay in the central box, compact and pressing. When defenders win it, roles swap: they use both boxes and the others all move into the central box and press.', 'Defending team confined to central box.', NULL, 'Open the pitch in possession, compact out of it, quick pressing, fast transitions.', '8v8 (16-20)', 16, 20, '40 x 40 m', 40.0, 40.0, 21.0, false, false, false, NULL, 270),
  ('8v8 dribble through corner gates', 'positional_game', 'opposed', 'in_possession', 76, 76, 'Speed Endurance Day - Positional: Practice 1', 'Adam Owen', 'Keep structure, spot space and react fast in transition.', '40x40m with a pole gate in each of the 4 corners.', 'Teams keep the ball and score by dribbling through any gate under control and stopping the ball beyond it. After a goal the other team restarts at once and the scorers recover and press.', 'Dribble through a gate and stop the ball = goal.', NULL, 'Positional balance, make the pitch big, see an open gate early, attack space with control, know your role.', '8v8 (16)', 16, 16, '40 x 40 m', 40.0, 40.0, 20.0, false, false, true, NULL, 280),
  ('8v8+2 wide neutrals to six small goals', 'small_sided_game', 'overload', 'in_possession', 77, 77, 'Speed Endurance Day - Positional: Practice 2', 'Adam Owen', 'Build with good shape and switch play to create chances.', '60x55m with 3 small goals at each end; 2 neutral full-backs/wingers on the sides support the team in possession.', 'Teams build with control and use the wide neutrals to stretch the play and switch the ball side to side at the right moment, then score in any of the 3 goals.', NULL, NULL, 'Team shape, support angles, width, retention, switching.', '8v8 +2 (18)', 18, 18, '60 x 55 m', 60.0, 55.0, 20.0, true, false, true, NULL, 290),
  ('8v8+4 wide targets, switch before end gates', 'positional_game', 'overload', 'in_possession', 78, 78, 'Speed Endurance Day - Positional: Practice 3', 'Adam Owen', 'Switch play and create space to score.', '50x70m in three lanes: 4v4 in the middle zone, 2v2 in each wide zone, 2 neutral targets at each end; gates at the ends.', 'Teams build through the middle and use the targets to switch from one side to the other; at least one switch is needed before scoring by passing through an end gate. Out of possession the middle players screen the centre to stop switches.', 'At least one switch before a goal through the end gates.', NULL, 'Wide players stay high and wide; far side stays open for the switch.', '8v8 +4 (20)', 20, 20, '50 x 70 m', 50.0, 70.0, 24.0, false, false, true, NULL, 300),
  ('9v9+2 four-zone play through the lines', 'positional_game', 'overload', 'in_possession', 79, 79, 'Speed Endurance Day - Positional: Practice 4', 'Adam Owen', 'Play through the lines using overloads and timed support.', '40x25m in 4 zones: 3v2 in zone 1, 2v2+joker in zones 2 and 3, 2v3 in zone 4.', 'Ball is passed into the next zone and the passer follows to make an overload (4v2 in zones 2-3). In zone 4 (3v3) they combine, then play long back to zone 1 or rebuild back through the zones. On loss the teams swap roles and reset.', 'Score by playing from zone 1 to 4 or by a target number of passes; passer follows the pass.', NULL, 'Build-up, overloads, positional play, timing of movement.', '9v9 +2 (20)', 20, 20, '40 x 25 m', 40.0, 25.0, 21.0, false, false, true, NULL, 310),
  ('9v9 build-up to target goalkeepers', 'positional_game', 'opposed', 'in_possession', 80, 80, 'Speed Endurance Day - Positional: Practice 5', 'Adam Owen', 'Structured build-up to find the target at the right moment.', '50x45m with a goalkeeper in a box at each end as a target; teams in shape (e.g. 4-2-3).', 'Teams keep the ball with positional structure and score by passing into the keeper''s hands (aerial catch); the keeper throws to the opposite keeper to restart.', 'Ball caught by the target GK = goal.', 'Set number of passes, or 2 passes inside the centre circle, before scoring.', 'Structure, support, retention, progression into the final third.', '9v9 or 10v10 + GKs (18-20 + GKs)', 20, 22, '50 x 45 m', 50.0, 45.0, 21.0, false, true, true, NULL, 320),
  ('10v10 three-zone overloads and switching', 'positional_game', 'overload', 'in_possession', 81, 81, 'Speed Endurance Day - Positional: Practice 6', 'Adam Owen', 'Create overloads and move the ball between zones with control.', '40x25m in zones split by mannequin lines, with a narrow target channel at each end holding a target player.', 'Play starts as a 3v2 plus target in one zone. Teams score by moving the ball zone to zone, target to target, or by a set number of passes. Once a pass crosses a mannequin line, an extra defender joins to make 3v3 plus target; defenders who win it pass into another zone and carry on.', 'Zones kept at 3v2 until the ball crosses a mannequin line.', NULL, 'Overloads, controlled switching between zones.', '10v10 +2 + GKs', 20, 22, '40 x 25 m', 40.0, 25.0, 16.0, false, true, true, NULL, 330),
  ('5v2 to 5v5: play through lines then press', 'transition', 'overload', 'to_defend', 82, 82, 'Speed Endurance Day - Positional: Practice 7', 'Adam Owen', 'Keep the ball under pressure, play through lines and react quickly.', '50x30m in two halves with pole gates on the halfway line and GKs at the ends.', 'Blues start 5(+GK)v2 wingers in one half. On the whistle 3 reds come in to make 5v5. After a pass target, blues play to the reds in the other half; then 2 blue wingers and 3 blues through the gates enter to press and rebuild 5v5 the other way.', 'Pass target before switching to the other half.', NULL, 'Retention under pressure, playing through lines, immediate press.', '10v10 + GKs', 20, 22, '50 x 30 m', 50.0, 30.0, 16.0, false, true, true, NULL, 340),
  ('10v10+3 central link players', 'positional_game', 'overload', 'in_possession', 83, 83, 'Speed Endurance Day - Positional: Practice 8', 'Adam Owen', 'Control possession with positional structure using central link players.', '45x50m with 3 neutral link players who stay inside the centre circle.', 'Teams keep the ball and use the link players to progress through midfield.', '10 straight passes, or playing through all 3 link players, = 1 goal.', NULL, 'Support angles, quick connections, spacing, forward play when on, patience, passing rhythm.', '10v10 +3 (23)', 23, 23, '45 x 50 m', 45.0, 50.0, 21.0, false, false, false, NULL, 350),
  ('10v10 build-up through midfield box to scoring zones', 'phase_of_play', 'opposed', 'in_possession', 84, 84, 'Speed Endurance Day - Positional: Practice 9', 'Adam Owen', 'Play through midfield and score in structured roles.', 'Half pitch, 10v10 (e.g. 4-3-3); central 3v3 midfield box; a wide goal zone in each corner for blues, a central goal zone for reds near halfway.', 'Coach starts with a pass to a centre back. Ball must pass through the midfield box before a goal. Blues score with a timed run to receive in a wide goal zone; reds score by finding their forward in the central zone, or by a set number of passes.', 'Midfielders stay in the box; no waiting in goal zones.', 'Two midfielders must combine in the box before a goal.', 'Structured roles, playing through midfield, drawing opponents.', '10v10 (20)', 20, 20, 'Half pitch', NULL, NULL, 22.0, false, true, true, NULL, 360),
  ('5v5 end to end through goalkeepers', 'positional_game', 'opposed', 'in_possession', 92, 92, 'Reaction Speed Day - Directional: Practice 1', 'Adam Owen', 'Keep the ball and play through the goalkeepers.', '40x25m central area with an 8m end zone at each end holding a goalkeeper; mannequins near each end zone.', 'Teams score by playing from one keeper to the other and back again, using angles round the mannequins and the keeper to link play forward.', 'GKs stay in their zones and use feet only.', NULL, 'Play through lines, GK in possession, receive on the half-turn, keep forward options.', '5v5 +GKs (10 + GKs)', 12, 12, '40 x 25 m', 40.0, 25.0, 20.0, false, true, true, NULL, 370),
  ('6v6 end-zone forward link to six mini goals', 'small_sided_game', 'opposed', 'in_possession', 93, 93, 'Reaction Speed Day - Directional: Practice 2', 'Adam Owen', 'Link play through the centre forward, combine and finish.', '35x20m: 5v5 in a 25x20m main area plus a 5m end zone at each end with a forward (2 touches) and 3 mini goals behind.', 'Teams pass into their forward in the end zone, support quickly, combine and finish in any of the 3 mini goals.', 'Players may enter the end zone only after the pass into the forward; forward 2 touches.', NULL, 'Support runs, third-man runs, angles to receive, link play with the forward, exploiting transitions.', '6v6 (12)', 12, 12, '35 x 20 m', 35.0, 20.0, 18.0, true, false, true, NULL, 380),
  ('3-team 5v2 switch through zones and press to score', 'transition', 'overload', 'to_attack', 94, 94, 'Reaction Speed Day - Directional: Practice 3', 'Adam Owen', 'Keep the ball, switch play and react fast in transition.', '25x15m in 3 zones (two end zones and a middle zone) with 4 small goals outside, 3 teams of 5.', 'Blues keep it 5v2 in one zone, complete a set number of passes and pass to reds in the far zone while 3 yellows in the middle screen. If the switch works, 2 yellows go across to press reds 5v2. Defenders who win it score at once in a small goal and swap roles with the team that lost it.', 'Set passes before switching; winners score immediately in a small goal.', NULL, 'Retention, switching, fast transition reactions.', '3 teams of 5 (15)', 15, 15, '25 x 15 m', 25.0, 15.0, 18.0, true, false, true, NULL, 390),
  ('7v7 progressive overloads, third-man finish', 'positional_game', 'overload', 'in_possession', 95, 95, 'Reaction Speed Day - Directional: Practice 4', 'Adam Owen', 'Progress through zones and score using the goalkeeper and third-man runs.', '45x20m in 5 zones with a neutral goalkeeper in each end zone; zone 1 2v1, middle zone 4+1v4, zone 3 1+2v2.', 'GK1 passes into zone 1 (2v1); the team plays into the middle and the passer moves up for a 5v4; then into zone 3 where 2 players push up for a 3v2. They score by combining with GK2 and getting a return pass on a third-man run. Roles reverse if the reds win it.', 'Passer moves forward to create the overload.', NULL, 'Progressive overloads, timing of third-man runs.', '7v7 +GKs (14 + GKs)', 16, 16, '45 x 20 m', 45.0, 20.0, 18.0, false, true, true, NULL, 400),
  ('6v6+3 hexagon central link transitions', 'transition', 'overload', 'to_defend', 97, 97, 'Reaction Speed Day - Transitional: Practice 1', 'Adam Owen', 'Combine through central players and react fast in transition.', '32x36m hexagon: 6 blue players on the outside edges, 3 yellow neutrals inside and 6 red defenders inside.', 'Blues keep the ball by linking play through the central yellows. If reds win it, roles change at once and the teams transition.', NULL, NULL, 'In possession: support, accuracy, central link play, forward thinking. Defending: intense press, close central lanes.', '6v6 +3 (15)', 15, 15, '32 x 36 m', 32.0, 36.0, 15.0, false, false, false, NULL, 410),
  ('3-team 7v7+7 heptagon rotational transition', 'transition', 'overload', 'to_defend', 98, 98, 'Reaction Speed Day - Transitional: Practice 2', 'Adam Owen', 'Keep the ball and react fast to losing it to win it back.', '35x35m heptagon: 7 blues on the outside, 7 yellows and 7 red defenders inside.', 'Blues and yellows keep possession together and score by completing a set number of passes. A team that loses it gets an extra point for winning it back within 5 passes and keeping it.', 'Set passes = 1 point; win back within 5 passes = extra point.', 'Outside team rotates in with the defenders on the coach''s whistle or after a team loses it twice.', 'Support, retention, regaining possession, role rotation.', '7v7 +7 (21)', 21, 21, '35 x 35 m', 35.0, 35.0, 18.0, false, false, false, NULL, 420),
  ('4-team inside-outside one-twos', 'transition', 'overload', 'to_defend', 99, 99, 'Reaction Speed Day - Transitional: Practice 3', 'Adam Owen', 'Combine quickly and accurately with support players and transition fast.', '25x20m with 6 cone gates round the edge; 4 teams of 3: two teams play 3v3 inside, two teams spread outside the gates as support.', 'The inside team in possession scores by playing quick one-twos with any outside player. After 3 scoring combinations they swap with an outside team; on the coach''s whistle all outside players swap with the inside players.', 'One-two with an outside player = score.', NULL, 'Combinations, support, passing speed, awareness, transition reactions.', '3v3 +6 (12)', 12, 12, '25 x 20 m', 25.0, 20.0, 18.0, false, false, false, NULL, 430),
  ('8v8+3 zonal possession, score in 3 passes', 'transition', 'overload', 'to_attack', 100, 100, 'Reaction Speed Day - Transitional: Practice 4', 'Adam Owen', 'Keep structure in possession and score quickly in transition.', '40x25m split into 4 zones with a small goal in each corner; each team keeps 2 players per zone (2v2); 3 jokers (one at each end, one floating) help the team in possession.', 'Blues keep the ball through their zonal structure, using the jokers to switch end to end. When reds win it they must score in a small goal within 3 passes while blues transition quickly to stop them.', '2 players per team in each zone; winners have max 3 passes to score.', NULL, 'Support, positional structure, retention, quick attacking transitions.', '8v8 +3 (19)', 19, 19, '40 x 25 m', 40.0, 25.0, 16.0, true, false, true, NULL, 440),
  ('6v6 4-2 lines to forwards, compact defending', 'small_sided_game', 'opposed', 'in_possession', 102, 102, 'Reaction Speed Day - Positional: Practice 1', 'Adam Owen', 'Play through the lines and defend compactly with organised recovery.', '20x30m with an end zone at each end holding 2 target forwards (F1, F2) and 2 small goals per end; each team set in two lines (4-2) in zones.', 'Teams move the ball to find the moment to play forward into F1 or F2, who combine quickly to score. Players hold their zones; one defender may recover back to pressure and defend the goals.', 'Players stay in their zones; only one recovering defender.', NULL, 'Ball speed, forward passing, playing through lines, screening central lanes, recovery runs.', '6v6 (12)', 12, 12, '20 x 30 m', 20.0, 30.0, 15.0, true, false, true, NULL, 450),
  ('5v5 outside plus 3v3 central square link play', 'positional_game', 'opposed', 'in_possession', 103, 103, 'Reaction Speed Day - Positional: Practice 2', 'Adam Owen', 'Keep structure and combine through the central midfield unit.', '30x22m: 5v5 around the outside, 3v3 inside a central square.', 'Team in possession uses its 3 central players to link play and progress through the middle. The square must stay 3v3, so when one player rotates out another must rotate in.', 'Central square always 3v3.', NULL, 'Positioning, body shape, awareness, timed rotations, playing into, through and beyond pressure.', '5v5 +3v3 (16)', 16, 16, '30 x 22 m', 30.0, 22.0, 20.0, false, false, false, NULL, 460),
  ('8v8+2 four-box positional overloads', 'possession', 'overload', 'in_possession', 104, 104, 'Reaction Speed Day - Positional: Practice 3', 'Adam Owen', 'Keep structure and use overloads to keep the ball.', '35x35m split into 4 boxes, 2v2 in each; 2 jokers move between boxes for the team in possession.', 'Players stay in their own boxes and the team scores by completing 8-10 straight passes across the boxes (10v8 with the jokers).', 'Phase 1: stay in own zones; 8-10 passes = goal.', 'Phase 2: defenders may leave their box to press while the team in possession keeps its 2-per-box shape.', 'Support, overloads, retention, switching, positional discipline.', '8v8 +2 (18)', 18, 18, '35 x 35 m', 35.0, 35.0, 20.0, false, false, false, NULL, 470),
  ('8v8 double box: press then expand', 'transition', 'opposed', 'to_attack', 105, 105, 'Reaction Speed Day - Positional: Practice 4', 'Adam Owen', 'Counter-press to win the ball, then use all the space to secure it.', '40x45m central box inside a 45x50m outer box.', 'Reds keep the ball 8v8 in the central box. When blues win it, 3 of them expand into the outer box to keep possession; reds cannot enter the outer box. If reds regain it they can send 3 out too.', '6-8 passes = score; blues max 2 touches in the outer box; reds may not enter it.', NULL, 'Quick expansion after winning it, positional balance, transition reactions.', '8v8 (16)', 16, 16, '45 x 50 m', 45.0, 50.0, 16.0, false, false, false, NULL, 480),
  ('8v8+5 four-zone overload to switch', 'positional_game', 'overload', 'in_possession', 106, 106, 'Reaction Speed Day - Positional: Practice 5', 'Adam Owen', 'Create and use overloads to switch play and keep the ball.', '35x35m in 4 equal zones with 2v2 in each; 3 yellow central jokers and 2 white end target players.', 'Game 1: score with 8-10 straight passes, making a 5v3 in a zone with 2 jokers and a target to progress. Game 2: score by switching from one target to the other. Game 3: 4v4 in each half with freedom to move and combine.', '8-10 passes = goal; target to target = goal.', 'Three game stages as listed.', 'Use space in possession, close space out of possession.', '8v8 +5 (21)', 21, 21, '35 x 35 m', 35.0, 35.0, 20.0, false, false, true, NULL, 490),
  ('10v5 overload with instant transition scoring', 'transition', 'overload', 'to_attack', 107, 107, 'Reaction Speed Day - Positional: Practice 6', 'Adam Owen', 'Keep the ball with patience and react fast to score in transition.', '45x35m with 4 small goals round the outside.', '10 blues keep the ball against 5 reds; after 10 passes blues may score in any of the 4 goals. If reds win it they can score at once in any goal.', 'Blues need 10 passes before scoring; a red goal counts triple (3 goals).', NULL, 'Support, retention, patience, transition reactions, finishing.', '10v5 (15)', 15, 15, '45 x 35 m', 45.0, 35.0, 16.0, true, false, false, NULL, 500)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'possession-with-purpose-to-maximise-performance-50-practices-youth-to-pro-traini') b;
